  (* [comment removed for export] *)
  Section Post.
    Variables (m' : mem) (j0 j1 j2 j3 : word) (b1 : Z).
    Hypothesis MU : munch W m m'.
    Hypothesis WM : wmono bsegs m m'.
    Hypothesis MI' : mem_inv bsegs m'.
    Hypothesis QC1' : rw_cells bsegs m' P [C4 (wz (cnt - 1)); C4 (wz (max_count c))].
    Hypothesis QC3' : u32arr bsegs m' (P + 16) (wlist (rev (tl chunks))).
    Hypothesis QC4' : stk bsegs m' (P + 16 + 4 * (cnt - 1)) (P + 80).
    Hypothesis QST' : rw_cells bsegs m' (TH + 208 + 2560) [C8 j0; C8 j1; C8 j2; C8 j3].
    Hypothesis HDR : rw_cells bsegs m' (U + -16) [C1 (b8 2); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz id)].
    Hypothesis B1 : b1_ok b1.
